import { resolveConfig } from "./config.js";
import { createLogger } from "./log.js";
import { resolveLanguage, strings } from "./i18n.js";
import { RescueManager } from "./rescue.js";
import { BufferPool } from "./buffer.js";
import { makeContextHook } from "./hooks.js";
import { runWatch, WATCHED_TYPES } from "./watch.js";
const plugin = {
    id: 'loop-recover',
    setup: async (rawCtx) => {
        const ctx = rawCtx;
        const cfg = resolveConfig(ctx.options);
        const log = createLogger(cfg.debugLog);
        const lang = resolveLanguage(cfg.language);
        const i18n = strings(lang);
        const dir = ctx.location?.directory;
        log(`setup mode=${cfg.mode} lang=${lang} app=${ctx.app.name}@${ctx.app.version} dir=${dir ?? '?'}`);
        const ops = {
            interrupt: (sessionID) => ctx.session.interrupt({ sessionID }),
            prompt: (sessionID, text) => ctx.session.prompt({ sessionID, text }),
            waitIdle: async (sessionID) => {
                try {
                    await ctx.session.wait({ sessionID });
                }
                catch (cause) {
                    // wait 不可用时退化固定退避，仍然续跑
                    log(`session.wait unavailable for ${sessionID}: ${cause}`);
                    await new Promise((resolve) => setTimeout(resolve, 1000));
                }
            },
            log,
        };
        const manager = new RescueManager(cfg, ops, lang, i18n);
        const buffers = new BufferPool(cfg.bufferChars);
        const abort = new AbortController();
        const registrations = [];
        // 关键：冷启动期完全"装死"——setup 立即返回，所有宿主 API 调用推迟到激活稳定后。
        // 激活期订阅可能回放积压事件并阻塞 fiber（/api/model 全 503 的根因猜测）。
        const init = (async () => {
            const delay = typeof ctx.options?.initDelayMs === 'number' ? ctx.options.initDelayMs : 3000;
            await new Promise((r) => setTimeout(r, delay));
            if (abort.signal.aborted)
                return;
            log('init: registering context hook');
            const reg = await Promise.race([
                ctx.session.hook('context', makeContextHook(cfg, manager, i18n, log)),
                new Promise((_, reject) => setTimeout(() => reject(new Error('hook registration timeout')), 10000)),
            ]);
            registrations.push(reg);
            log('init: context hook registered');
            log('init: subscribing events');
            const events = ctx.event.subscribe({ types: [...WATCHED_TYPES] });
            await runWatch({ events, directory: dir, cfg, manager, buffers, log }, abort.signal);
            log('init: event stream ended');
        })().catch((cause) => log(`init failed: ${cause}`));
        return async () => {
            abort.abort();
            await init;
            for (const reg of registrations)
                await reg.dispose().catch(() => { });
            log('disposed');
        };
    },
};
export default plugin;

/**
 * opencode-loop-recover — 服务端入口。
 *
 * default export { id, setup }（Promise API），加载约定见
 * packages/core/src/plugin/module.ts 的 Module schema。
 */
import type { Plugin } from '@opencode/plugin'
import { resolveConfig } from './config.ts'
import { createLogger } from './log.ts'
import { resolveLanguage, strings } from './i18n.ts'
import { RescueManager, type RescueOps } from './rescue.ts'
import { BufferPool } from './buffer.ts'
import { makeContextHook } from './hooks.ts'
import { runWatch, WATCHED_TYPES, type EventLike } from './watch.ts'

interface SessionOpsLike {
  interrupt(input: { sessionID: string; resume?: boolean }): Promise<unknown>
  prompt(input: { sessionID: string; text: string }): Promise<unknown>
  wait(input: { sessionID: string }): Promise<unknown>
}

interface EventDomainLike {
  subscribe(input?: { types?: readonly string[] }): AsyncIterable<EventLike>
}

interface HookRegistrar {
  (name: string, callback: (input: never) => Promise<void>): Promise<{ dispose(): Promise<void> }>
}

interface CtxLike {
  options: Record<string, unknown>
  app: { name: string; version: string; channel: string }
  event: EventDomainLike
  session: SessionOpsLike & { hook: HookRegistrar }
}

const plugin: Plugin.Plugin = {
  id: 'loop-recover',

  setup: async (rawCtx) => {
    const ctx = rawCtx as unknown as CtxLike
    const cfg = resolveConfig(ctx.options)
    const log = createLogger(cfg.debugLog)
    const lang = resolveLanguage(cfg.language)
    const i18n = strings(lang)

    const dir = (ctx as { location?: { directory?: string } }).location?.directory
    log(`setup mode=${cfg.mode} lang=${lang} app=${ctx.app.name}@${ctx.app.version} dir=${dir ?? '?'}`)

    const ops: RescueOps = {
      interrupt: (sessionID) => ctx.session.interrupt({ sessionID }),
      prompt: (sessionID, text) => ctx.session.prompt({ sessionID, text }),
      waitIdle: async (sessionID) => {
        try {
          await ctx.session.wait({ sessionID })
        } catch (cause) {
          // wait 不可用时退化固定退避，仍然续跑
          log(`session.wait unavailable for ${sessionID}: ${cause}`)
          await new Promise((resolve) => setTimeout(resolve, 1000))
        }
      },
      log,
    }

    const manager = new RescueManager(cfg, ops, lang, i18n)
    const buffers = new BufferPool(cfg.bufferChars)

    const abort = new AbortController()
    const registrations: Array<{ dispose(): Promise<void> }> = []

    // 关键：冷启动期完全"装死"——setup 立即返回，所有宿主 API 调用推迟到激活稳定后。
    // 激活期订阅可能回放积压事件并阻塞 fiber（/api/model 全 503 的根因猜测）。
    const init = (async () => {
      const delay = typeof ctx.options?.initDelayMs === 'number' ? ctx.options.initDelayMs : 3000
      await new Promise((r) => setTimeout(r, delay))
      if (abort.signal.aborted) return
      log('init: registering context hook')
      const reg = await Promise.race([
        ctx.session.hook('context', makeContextHook(cfg, manager, i18n, log) as never),
        new Promise<never>((_, reject) => setTimeout(() => reject(new Error('hook registration timeout')), 10000)),
      ])
      registrations.push(reg)
      log('init: context hook registered')

      log('init: subscribing events')
      const events = ctx.event.subscribe({ types: [...WATCHED_TYPES] })
      await runWatch({ events, directory: dir, cfg, manager, buffers, log }, abort.signal)
      log('init: event stream ended')
    })().catch((cause) => log(`init failed: ${cause}`))

    return async () => {
      abort.abort()
      await init
      for (const reg of registrations) await reg.dispose().catch(() => {})
      log('disposed')
    }
  },
}

export default plugin

/**
 * opencode-loop-recover — GUI 插件的 main 进程入口。
 *
 * 桌面 main 进程持有 Node fs 权限；这里负责把设置页的 options 补丁写回全局
 * opencode.json(c)（与 `opencode plugin add` 相同的 jsonc 保注释编辑 + tmp/rename 原子写）。
 * opencode 的 config watcher 看到文件变化后自动重载 server 与 GUI 插件，新 options 生效。
 */
import { mkdir, readFile, rename, stat, writeFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import path from 'node:path'
import type { Plugin } from '@opencode/plugin/gui'
import { ConfigIpc } from './contract.ts'
import { patchPluginOptions, readPluginOptions } from './config-patch.ts'

/** 全局配置目录：与 @opencode/util/global 相同规则。 */
function configDirectory(): string {
  if (process.env.OPENCODE_CONFIG_DIR) return process.env.OPENCODE_CONFIG_DIR
  const xdg = process.env.XDG_CONFIG_HOME ?? path.join(homedir(), '.config')
  return path.join(xdg, 'opencode')
}

/** 与 CLI resolveConfigPath 相同的候选顺序；都不存在时返回第一个。 */
async function resolveConfigPath(): Promise<string> {
  const directory = configDirectory()
  const candidates = [
    path.join(directory, 'opencode.json'),
    path.join(directory, 'opencode.jsonc'),
    path.join(directory, '.opencode', 'opencode.json'),
    path.join(directory, '.opencode', 'opencode.jsonc'),
  ]
  for (const candidate of candidates) {
    const exists = await stat(candidate).then(
      (info) => info.isFile(),
      () => false,
    )
    if (exists) return candidate
  }
  return candidates[0]
}

const readConfigText = async (file: string): Promise<string> =>
  readFile(file, 'utf8').catch((error: unknown) => {
    if (typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT') return '{}'
    throw error
  })

const main: Plugin.MainSetup = (ctx) => {
  ctx.provide(ConfigIpc, {
    configPath: () => resolveConfigPath(),
    getOptions: async () => readPluginOptions(await readConfigText(await resolveConfigPath())),
    setOptions: async (patch) => {
      const file = await resolveConfigPath()
      const updated = patchPluginOptions(await readConfigText(file), patch)
      await mkdir(path.dirname(file), { recursive: true })
      const temporary = `${file}.tmp`
      await writeFile(temporary, updated, { mode: 0o600 })
      await rename(temporary, file)
      ctx.log.write('info', 'loop-recover options updated', { file })
    },
  })
}

export default main
